UPDATE finance_management fm SET deleted = true, updated_at = now() FROM ( VALUES
(#{p.companyId}::bigint, #{p.childId}::bigint)
) AS scope(company_id, finance_id) WHERE fm.company_id = scope.company_id AND fm.finance_id = scope.finance_id AND fm.deleted = false AND fm.sync_id != #{syncId}::uuid
